import{_ as s,a8 as a,o as d,c,ah as _,a as t,a3 as o,K as i,L as p}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const w=JSON.parse('{"title":"飞书 wiki 节点无法用 API 设为互联网公开（1066001）","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["飞书","wiki","权限",1066001,"对外发布"]},"headers":[],"relativePath":"vault/Memory/Lessons/飞书wiki节点公开API失败1066001.md","filePath":"vault/Memory/Lessons/飞书wiki节点公开API失败1066001.md","lastUpdated":1789374053000}'),u={name:"vault/Memory/Lessons/飞书wiki节点公开API失败1066001.md"};function h(m,e,k,b,P,g){const r=a("VPNolebaseInlineLinkPreview"),l=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return d(),c("div",null,[e[3]||(e[3]=_('<h1 id="飞书-wiki-节点无法用-api-设为互联网公开-1066001" tabindex="-1">飞书 wiki 节点无法用 API 设为互联网公开（1066001） <a class="header-anchor" href="#飞书-wiki-节点无法用-api-设为互联网公开-1066001" aria-label="Permalink to “飞书 wiki 节点无法用 API 设为互联网公开（1066001）”">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to “现象”">​</a></h2><p>想把飞书知识库节点设为「互联网只读公开」时：</p><ul><li><code>lark-cli drive +permission-get-setting</code> 查到 <code>manage_public</code> 权限 <code>auth_result=true</code>；</li><li>但 <code>permission.public patch</code> 设 <code>link_share_entity:&quot;anyone_readable&quot;</code> 返回 <strong><code>1066001 Internal Error</code></strong>；</li><li>wiki 类型节点不支持 <code>external_access</code> 参数，文档交付物直接给链接会被拦。</li></ul><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to “根因”">​</a></h2><p>飞书知识库的「发布到互联网」是管理员级操作，不在开放 API（<code>permission.public</code>）的覆盖范围内；即便 connector 拥有 <code>manage_public</code> 权限，API 仍拒绝。</p><h2 id="解法" tabindex="-1">解法 <a class="header-anchor" href="#解法" aria-label="Permalink to “解法”">​</a></h2><ul><li><strong>必须由管理员在 UI 操作</strong>：飞书知识库设置 → 「将知识库发布到互联网」（生成只读分享链接）。</li><li>若走程序化交付，改导出 <strong>PDF</strong>（<code>lark-cli drive +export --file-extension pdf</code>，无飞书水印）或本地渲染截图作为兜底交付物。</li><li>规划「对外给飞书链接」的需求时，<strong>提前请用户在 UI 完成发布</strong>，不要指望 API 能代劳。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2>',9)),t("ul",null,[t("li",null,[e[1]||(e[1]=o("富文本 / 本地图写入手法见 ",-1)),i(r,{class:"route-link nolebase-route-link-invalid",href:"#",target:"_target"},{default:p(()=>[...e[0]||(e[0]=[o("Memory/Workflows/飞书知识库写入(lark-cli链路)",-1)])]),_:1}),e[2]||(e[2]=o("。",-1))])]),i(l),i(n)])}const x=s(u,[["render",h]]);export{w as __pageData,x as default};
